    beats = {
        { id = "jelly", at = 15, title = "One of thousands",
            text = "I began as a dot in a cloud of jelly, one of several thousand. No name, no voice, no legs. The whole cast looked exactly like me. Even then I felt, strongly, that I was the lead." },
        { id = "tail", at = 40, title = "All tail",
            text = "Then I was a tadpole: a head with a tail attached, and no way to say a word. Imagine. Me, silent, a whole spring. I wriggled with great expression. Nobody reviewed the wriggling." },
        { id = "legs", at = 80, title = "Legs",
            text = "The back legs came first, then the front, like props arriving late. The tail went, bit by bit, into the rest of me. I still carry that tail, in a sense. A frog keeps the first act inside." },
        { id = "note", at = 140, title = "The first note",
            text = "My first croak came out as a squeak. A passing duck laughed. I practised under a dock leaf every evening until the squeak had a floor and a ceiling. Then I went looking for a stage." },
        { id = "choir", at = 220, title = "The great choir",
            text = "There was a marsh nearby with a choir of hundreds. I sang with them one whole summer. Glorious, deafening, and no one could pick out a single voice. I sang my best verse and the frog beside me asked if I had said something." },
        { id = "road", at = 320, title = "The road in the rain",
            text = "One wet night I left. Frogs travel in rain, when the ground is kind to skin. I crossed a field, a ditch and a dark hard strip that smelled of thunder. I had no idea where I was going. I told myself: toward an audience." },
        { id = "pond", at = 450, title = "The small pond",
            text = "I found this pond. Small, deep, good reeds, no choir at all. I sang the first night and my own voice came back off the wall. A solo, at last! I waited for the applause. The reeds moved a little." },
        { id = "empty", at = 600, title = "Empty house",
            text = "I sang here every night that summer. Jokes, ballads, the long one about the moon. Nobody came. I will tell you what I have told no newt: some nights I sang quietly, so as not to hear how alone the echo was." },
        { id = "window", at = 800, title = "The window",
            text = "One evening a light came on in the house and a window opened a hand's width. I sang as I had never sung. The window stayed open until I finished. Then shut, softly. Softly! That is how one shuts a window on a song one liked." },
        { id = "reader", at = 1050, title = "A full house",
            text = "And then you came down to the bank with a book. I gave you everything. The moon ballad, both cheeks. You read through the lot, and at the end you looked up and smiled, straight at me. A full house. One seat." },
        { id = "quiet", at = 1400, title = "The quiet art",
            text = "I have watched you through {total} pages. You sit in silence and whole worlds play in your head. No stage, no cheeks, no moon. I used to think a story had to be loud to be real. You are teaching an old ham the quiet kind." },
        { id = "verse", at = 1800, title = "The next verse",
            text = "I wanted a marsh full of listeners. I got one, {days} days ago, and I would not trade. When I rest in the winter mud I hear you turning pages up above, like soft clapping. That is all the applause I want. Stay for the next verse. I wrote the verse for you." },
    },
